    @Override // android.view.View
    public boolean onTouchEvent(MotionEvent event) {
        if (event.getAction() == 0) {
            if (!this.tapping) {
                this.tapStartTime = System.currentTimeMillis();
                this.tapCount = 1;
                this.tapping = true;
            } else if (System.currentTimeMillis() < this.tapStartTime + 450) {
                this.tapCount++;
            }
        }
        if (this.currentTouchEvents < this.maxTouchEvents) {
            this.storedTouchEvents[this.currentTouchEvents].downTime = event.getDownTime();
            this.storedTouchEvents[this.currentTouchEvents].motion = event.getAction();
            this.storedTouchEvents[this.currentTouchEvents].currX = (int) event.getX();
            this.storedTouchEvents[this.currentTouchEvents].currY = (int) event.getY();
            this.currentTouchEvents++;
        } else if (event.getAction() == 1) {
            for (int iter = this.maxTouchEvents - 1; iter >= 0; iter--) {
                if (this.storedTouchEvents[iter].motion == 2 || this.storedTouchEvents[iter].motion == 0) {
                    this.storedTouchEvents[iter].downTime = event.getDownTime();
                    this.storedTouchEvents[iter].motion = event.getAction();
                    this.storedTouchEvents[iter].currX = (int) event.getX();
                    this.storedTouchEvents[iter].currY = (int) event.getY();
                    break;
                }
            }
        }
        return true;
    }
